namespace ghidra.app.util.viewer.format.actions;

using ghidra.app.util;
using ghidra.app.util.viewer.format;
using ghidra.util;
using docking;
using docking.action;
using docking.action;

/**
 * Action for removing empty rows.
 */
public class RemoveRowAction : DockingAction {
	private FieldHeaderLocation loc;
	private FieldHeader panel;

    public RemoveRowAction(string owner, FieldHeader panel) : base("Remove Row", owner, false)
    {
        this.panel = panel;
        setPopupMenuData( new MenuData( new string[] {"Remove Row"}, null, "field" ) );
        setEnabled(true);
		setHelpLocation(new HelpLocation(HelpTopics.CODE_BROWSER, "Remove Row"));
    }

    /* @Override */
    public bool isEnabledForContext(ActionContext context) {
        object contextObject = context.getContextObject();
		if (contextObject is FieldHeaderLocation) {
			loc = (FieldHeaderLocation)contextObject;
			int row = loc.getRow();
			FieldFormatModel model = loc.getModel();
			return row < model.getNumRows() && (model.getNumFactorys(row) == 0);
		}
		return false;
	}

    /* @Override */
    public void actionPerformed(ActionContext context) {
    	panel.setTabLock( true );
		loc.getModel().removeRow(loc.getRow());		
		panel.getHeaderTab().update();
    }
}

